mapper.select:
SELECT
        (SELECT COUNT(*) FROM `user`) AS totalUsers,

        (SELECT COUNT(*) FROM `user`
         WHERE DATE(created_at) = CURDATE()
    ) AS newUsersToday,

    (SELECT COUNT(DISTINCT user_id) FROM operation_log
WHERE DATE(created_at) = CURDATE()
    ) AS activeUsersToday,

    (SELECT COUNT(*) FROM document
WHERE deleted_at IS NULL
    ) AS totalNotes,

    (SELECT COUNT(*) FROM knowledge_base
WHERE deleted = 0
    ) AS totalKbs,

    (SELECT COUNT(*) FROM comment
    ) AS totalComments

SELECT d.id, d.title, d.type, d.content, d.kb_id AS kbId, kb.name AS kbName, d.creator_id AS creatorId, u.name AS creatorName, d.audit_status AS auditStatus, d.is_public AS isPublic, CASE WHEN d.deleted_at IS NOT NULL THEN TRUE ELSE FALSE END AS deleted, d.view_count AS viewCount, d.like_count AS likeCount, d.comment_count AS commentCount, d.created_at AS createdAt, d.updated_at AS updatedAt FROM document d LEFT JOIN knowledge_base kb ON d.kb_id = kb.id AND kb.deleted = 0 LEFT JOIN user u ON d.creator_id = u.id
AND d.deleted_at IS NULL AND d.id NOT IN (SELECT note_id FROM document_embed)
AND d.title LIKE CONCAT('%', #{keyword}, '%')
AND d.type = #{type}
AND d.audit_status = #{auditStatus}
AND d.kb_id = #{kbId}
AND d.creator_id = #{creatorId}
AND d.created_at >= #{startTime}
AND d.created_at <= #{endTime}
ORDER BY d.created_at DESC

mapper.update:
UPDATE document
title = #{title}, content = #{content}, version = #{version}, last_editor_id = #{lastEditorId}, updated_at = #{updatedAt}
WHERE id = #{id}

