UPDATE document
SET audit_status = #{auditStatus}
WHERE id = #{noteId}

mapper.select:
SELECT kb.id, kb.name, kb.description, kb.cover_url AS coverUrl, kb.is_public AS isPublic, COALESCE(dc.doc_count, 0) AS docCount, u.name AS creatorName, kb.created_at AS createdAt FROM knowledge_base kb LEFT JOIN user u ON kb.creator_id = u.id LEFT JOIN ( SELECT kb_id, COUNT(*) AS doc_count FROM document WHERE deleted_at IS NULL GROUP BY kb_id ) dc ON kb.id = dc.kb_id WHERE kb.deleted = 0
AND kb.name LIKE CONCAT('%', #{keyword}, '%')
AND kb.is_public = #{isPublic}
AND kb.creator_id = #{creatorId}
ORDER BY kb.created_at DESC
